// DO NOT EDIT THIS FILE.

const API = "/api/students";
const COLUMNS = [
  { key: "name", label: "Name" },
  { key: "dept", label: "Department" },
  { key: "city", label: "City" },
  { key: "marks", label: "Marks" }
];
const NUMBER_FIELDS = ["marks"];

const resultTitle = document.querySelector("#result-title");
const resultBox = document.querySelector("#result");
const addStatus = document.querySelector("#add-status");

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function showMessage(text, type) {
  resultBox.innerHTML = `<p class="message ${type}">${escapeHtml(text)}</p>`;
}

function showTable(title, list) {
  resultTitle.textContent = `${title} (${list.length} found)`;
  if (list.length === 0) {
    showMessage("No students found.", "info");
    return;
  }
  const head = COLUMNS.map((col) => `<th>${col.label}</th>`).join("");
  const body = list
    .map((row) => `<tr>${COLUMNS.map((col) => `<td>${escapeHtml(row[col.key])}</td>`).join("")}</tr>`)
    .join("");
  resultBox.innerHTML = `<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`;
}

async function readJson(response) {
  try {
    return await response.json();
  } catch {
    return {};
  }
}

async function loadList(title, url) {
  resultTitle.textContent = title;
  showMessage("Loading...", "info");
  try {
    const response = await fetch(url);
    const data = await readJson(response);
    if (!response.ok) {
      showMessage(data.error || "The database query failed.", "error");
      return;
    }
    showTable(title, data);
  } catch {
    showMessage("Could not reach the server. Is it running?", "error");
  }
}

function showAll() {
  loadList("All students", API);
}

document.querySelector("#show-all").addEventListener("click", showAll);

document.querySelector("#top-three").addEventListener("click", () => {
  loadList("Top 3 students by marks", `${API}/top`);
});

document.querySelector("#search-form").addEventListener("submit", (event) => {
  event.preventDefault();
  const value = event.target.dept.value;
  loadList(`Students with dept ${value}`, `${API}/search?dept=${encodeURIComponent(value)}`);
});

document.querySelector("#filter-form").addEventListener("submit", (event) => {
  event.preventDefault();
  const value = event.target.minMarks.value;
  loadList(`Students with marks of at least ${value}`, `${API}/filter?minMarks=${encodeURIComponent(value)}`);
});

document.querySelector("#add-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const form = event.target;
  const student = Object.fromEntries(new FormData(form));
  for (const field of NUMBER_FIELDS) {
    student[field] = Number(student[field]);
  }

  addStatus.className = "status";
  addStatus.textContent = "Saving...";
  try {
    const response = await fetch(API, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(student),
    });
    const data = await readJson(response);
    if (!response.ok) {
      addStatus.className = "status error";
      addStatus.textContent = data.error || "The student was not saved.";
      return;
    }
    addStatus.className = "status success";
    addStatus.textContent = `Student saved: ${data.name}`;
    form.reset();
    showAll();
  } catch {
    addStatus.className = "status error";
    addStatus.textContent = "Could not reach the server. Is it running?";
  }
});

showAll();
